        return !hasErrors
    }

    private fun loadExistingUserData() {
        viewModelScope.launch {
            try {
                val response = apiService.getCurrentUser()
                if (response.isSuccessful) {
                    val user = response.body()
                    user?.let {
                        _uiState.value = _uiState.value.copy(
                            firstName = it.firstName,
                            lastName = it.lastName,
                            selectedGenreIds = it.prefferredGenreIds.toSet()
                        )
                    }
                }
                // If it fails, just keep empty fields for new users
            } catch (e: Exception) {
                // If it fails, just keep empty fields for new users
            }
        }
    }

    fun saveProfile(onComplete: (Boolean) -> Unit) {
        if (!validateFields()) {
            onComplete(false)
            return
        }

        viewModelScope.launch {
            _uiState.value = _uiState.value.copy(
                isSaving = true,
                saveError = null
            )

            try {
                val state = _uiState.value
                val request = CreateUserRequest(
                    firstName = state.firstName.trim(),
                    lastName = state.lastName.trim(),
                    preferredGenreIds = state.selectedGenreIds.toList(),
                    email = tokenManager.getUserEmail() ?: ""
                )

                val response = apiService.createUser(request)

                if (response.isSuccessful) {
                    val updatedUser = response.body()

                    // Update local user info: usar role del response si existe, sino fallback al tokenManager o "READER"
                    updatedUser?.let { user ->
                        val roleToSave = user.roleName ?: tokenManager.getUserRole() ?: "READER"
                        tokenManager.saveUserInfo(
                            userId = user.id.toString(),
                            email = tokenManager.getUserEmail() ?: "",
                            name = "${user.firstName} ${user.lastName}",
                            role = roleToSave
                        )
                    }

                    _uiState.value = _uiState.value.copy(isSaving = false)
                    onComplete(true)
                } else {
                    val errorMessage = when (response.code()) {
                        400 -> "Datos inválidos. Por favor verifica la información."
                        401 -> "Sesión expirada. Por favor inicia sesión nuevamente."
                        500 -> "Error del servidor. Inténtalo más tarde."
                        else -> "Error al guardar el perfil: ${response.code()}"
                    }

                    _uiState.value = _uiState.value.copy(
                        saveError = errorMessage,
                        isSaving = false
                    )
                    onComplete(false)
                }
            } catch (e: Exception) {
                _uiState.value = _uiState.value.copy(
                    saveError = "Error de conexión: ${e.message}",
                    isSaving = false
                )
                onComplete(false)
            }
        }
    }
}
